-- @seq 146
CREATE FUNCTION public.acct_bank_account_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE a acct_chart_of_accounts%ROWTYPE;
BEGIN
  SELECT * INTO a FROM acct_chart_of_accounts WHERE id = NEW.gl_account_id;
  IF NOT FOUND OR a.tenant_id <> NEW.tenant_id OR a.entity_id <> NEW.entity_id THEN
    RAISE EXCEPTION 'Register GL account must belong to the same company'; END IF;
  IF NEW.account_kind IN ('credit_card','line_of_credit','loan') AND a.account_type <> 'liability' THEN
    RAISE EXCEPTION '% registers must point at a liability account (got % %)', NEW.account_kind, a.code, a.account_type; END IF;
  IF NEW.account_kind IN ('checking','savings','money_market','cash','petty_cash','undeposited_funds','payment_processor') AND a.account_type <> 'asset' THEN
    RAISE EXCEPTION '% registers must point at an asset account (got % %)', NEW.account_kind, a.code, a.account_type; END IF;
  UPDATE acct_chart_of_accounts SET is_reconcilable = true, is_bank_feed = true WHERE id = a.id AND NOT (is_reconcilable AND is_bank_feed);
  RETURN NEW;
END $$;

-- @seq 147
CREATE FUNCTION public.acct_bank_descriptor_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.normalized_descriptor := acct_normalize_descriptor(coalesce(NEW.payee, NEW.description));
  RETURN NEW;
END $$;

-- @seq 148
CREATE FUNCTION public.acct_bank_gl(p_bank_account_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
  SELECT gl_account_id INTO v FROM acct_bank_accounts WHERE id = p_bank_account_id AND is_active;
  IF v IS NULL THEN RAISE EXCEPTION 'Bank/card account % not found or inactive (pass an acct_bank_accounts id, not a chart-of-accounts id)', p_bank_account_id; END IF;
  RETURN v;
END $$;

-- @seq 149
CREATE FUNCTION public.acct_bank_match_candidates(p_bank_txn_id uuid, p_days integer DEFAULT 10) RETURNS TABLE(journal_line_id uuid, journal_entry_id uuid, entry_no bigint, posting_date date, amount numeric, memo text, source text, day_diff integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT l.id, e.id, e.entry_no, e.posting_date, l.debit - l.credit, coalesce(l.description, e.memo), e.source,
         abs(e.posting_date - t.transaction_date)
    FROM acct_bank_transactions t
    JOIN acct_bank_accounts b ON b.id = t.bank_account_id
    JOIN acct_journal_lines l ON l.account_id = b.gl_account_id
    JOIN acct_journal_entries e ON e.id = l.journal_entry_id AND e.status = 'posted'
   WHERE t.id = p_bank_txn_id AND acct_can_access(t.tenant_id)
     AND l.debit - l.credit = t.amount AND l.cleared_status = 'uncleared'
     AND abs(e.posting_date - t.transaction_date) <= p_days
     AND NOT EXISTS (SELECT 1 FROM acct_bank_transactions x WHERE x.matched_journal_line_id = l.id)
   ORDER BY abs(e.posting_date - t.transaction_date), e.entry_no;
$$;

-- @seq 150
CREATE FUNCTION public.acct_bank_rule_matches(p_rule_id uuid, p_txn_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_bank_rules%ROWTYPE; t acct_bank_transactions%ROWTYPE; c record; v_hit boolean; v_any boolean := false; v_all boolean := true;
        v_text text; v_val text; v_n int := 0; v_amt numeric;
BEGIN
  SELECT * INTO r FROM acct_bank_rules WHERE id = p_rule_id;
  SELECT * INTO t FROM acct_bank_transactions WHERE id = p_txn_id;
  IF r.applies_to = 'money_out' AND t.amount >= 0 THEN RETURN false; END IF;
  IF r.applies_to = 'money_in'  AND t.amount <= 0 THEN RETURN false; END IF;
  IF r.bank_account_ids IS NOT NULL AND NOT t.bank_account_id = ANY (r.bank_account_ids) THEN RETURN false; END IF;
  v_amt := abs(t.amount);
  FOR c IN SELECT * FROM acct_bank_rule_conditions WHERE rule_id = p_rule_id LOOP
    v_n := v_n + 1;
    IF c.field = 'amount' THEN
      v_hit := CASE c.operator
        WHEN 'equals' THEN v_amt = c.value::numeric  WHEN 'not_equals' THEN v_amt <> c.value::numeric
        WHEN 'gt' THEN v_amt > c.value::numeric      WHEN 'gte' THEN v_amt >= c.value::numeric
        WHEN 'lt' THEN v_amt < c.value::numeric      WHEN 'lte' THEN v_amt <= c.value::numeric
        WHEN 'between' THEN v_amt BETWEEN c.value::numeric AND c.value2::numeric
        ELSE false END;
    ELSE
      v_text := CASE c.field WHEN 'description' THEN t.description WHEN 'payee' THEN t.payee WHEN 'reference' THEN t.reference
                ELSE concat_ws(' ', t.description, t.payee, t.reference) END;
      v_text := coalesce(v_text, ''); v_val := c.value;
      IF NOT c.case_sensitive THEN v_text := lower(v_text); v_val := lower(v_val); END IF;
      v_hit := CASE c.operator
        WHEN 'contains' THEN strpos(v_text, v_val) > 0       WHEN 'not_contains' THEN strpos(v_text, v_val) = 0
        WHEN 'equals' THEN v_text = v_val                    WHEN 'not_equals' THEN v_text <> v_val
        WHEN 'starts_with' THEN left(v_text, length(v_val)) = v_val
        WHEN 'ends_with' THEN right(v_text, length(v_val)) = v_val
        WHEN 'regex' THEN CASE WHEN c.case_sensitive THEN v_text ~ c.value ELSE v_text ~* c.value END
        ELSE false END;
    END IF;
    v_any := v_any OR v_hit; v_all := v_all AND v_hit;
  END LOOP;
  IF v_n = 0 THEN RETURN false; END IF;
  RETURN CASE WHEN r.match_mode = 'all' THEN v_all ELSE v_any END;
END $$;

-- @seq 151
CREATE FUNCTION public.acct_bank_txn_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  SELECT entity_id INTO NEW.entity_id FROM acct_bank_accounts WHERE id = NEW.bank_account_id;
  IF NEW.transaction_hash IS NULL AND NEW.provider_transaction_id IS NULL THEN
    -- manual/CSV imports: hash date + amount + description + per-day occurrence
    NEW.transaction_hash := encode(sha256(convert_to(NEW.bank_account_id::text || NEW.transaction_date || NEW.amount::text || coalesce(lower(NEW.description),'') ||
       (SELECT count(*) FROM acct_bank_transactions t WHERE t.bank_account_id = NEW.bank_account_id AND t.transaction_date = NEW.transaction_date
           AND t.amount = NEW.amount AND coalesce(lower(t.description),'') = coalesce(lower(NEW.description),''))::text, 'UTF8')), 'hex');
  END IF;
  RETURN NEW;
END $$;

