-- @seq 279
CREATE FUNCTION public.acct_reconciliation_mark(p_reconciliation_id uuid, p_journal_line_ids uuid[], p_cleared boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_reconciliations%ROWTYPE; b acct_bank_accounts%ROWTYPE; n int;
BEGIN
  SELECT * INTO r FROM acct_reconciliations WHERE id = p_reconciliation_id;
  PERFORM acct_assert_access(r.tenant_id);
  IF r.status NOT IN ('open','in_progress','reopened') THEN RAISE EXCEPTION 'Reconciliation is %', r.status; END IF;
  SELECT * INTO b FROM acct_bank_accounts WHERE id = r.bank_account_id;
  UPDATE acct_journal_lines l SET
         reconciliation_id = CASE WHEN p_cleared THEN r.id END,
         cleared_status = CASE WHEN p_cleared THEN 'cleared' ELSE 'uncleared' END,
         cleared_at = CASE WHEN p_cleared THEN now() END
    FROM acct_journal_entries e
   WHERE l.id = ANY (p_journal_line_ids) AND e.id = l.journal_entry_id AND l.account_id = b.gl_account_id
     AND l.cleared_status <> 'reconciled' AND e.posting_date <= r.as_of_date;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n;
END $$;

-- @seq 280
CREATE FUNCTION public.acct_reconciliation_summary(p_reconciliation_id uuid) RETURNS TABLE(beginning_balance numeric, cleared_deposits numeric, cleared_payments numeric, cleared_balance numeric, statement_ending_balance numeric, difference numeric, uncleared_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_reconciliations%ROWTYPE; b acct_bank_accounts%ROWTYPE; v_sign int;
BEGIN
  SELECT * INTO r FROM acct_reconciliations WHERE id = p_reconciliation_id;
  PERFORM acct_assert_access(r.tenant_id);
  SELECT * INTO b FROM acct_bank_accounts WHERE id = r.bank_account_id;
  v_sign := CASE WHEN b.account_kind IN ('credit_card','line_of_credit','loan') THEN -1 ELSE 1 END;
  SELECT r.beginning_balance,
         coalesce(sum(l.debit)  FILTER (WHERE l.reconciliation_id = r.id), 0),
         coalesce(sum(l.credit) FILTER (WHERE l.reconciliation_id = r.id), 0),
         count(*) FILTER (WHERE l.reconciliation_id IS NULL AND l.cleared_status <> 'reconciled')::int
    INTO beginning_balance, cleared_deposits, cleared_payments, uncleared_count
    FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id AND e.status IN ('posted','reversed')
   WHERE l.account_id = b.gl_account_id
     AND ((e.posting_date <= r.as_of_date AND l.cleared_status <> 'reconciled') OR l.reconciliation_id = r.id);
  cleared_balance := r.beginning_balance + v_sign * (cleared_deposits - cleared_payments);
  statement_ending_balance := r.statement_balance;
  difference := r.statement_balance - cleared_balance;
  RETURN NEXT;
END $$;

-- @seq 592
CREATE FUNCTION public.teller_ingest_transactions(p_account_ref uuid, p_items jsonb, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_full_window boolean DEFAULT false) RETURNS TABLE(upserted integer, sent_to_feed integer, pending integer, removed integer, held_sign_unconfirmed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE a teller_accounts%ROWTYPE; ba acct_bank_accounts%ROWTYPE; it jsonb; v_sign smallint; v_tt uuid; v_bt uuid;
        n_up int := 0; n_feed int := 0; n_pend int := 0; n_rem int := 0; n_hold int := 0; v_ids text[] := '{}'; v_amt numeric;
BEGIN
  SELECT * INTO a FROM teller_accounts WHERE id = p_account_ref FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Teller account %', p_account_ref; END IF;
  SELECT money_in_sign INTO v_sign FROM teller_sign_convention WHERE account_type = a.account_type;
  IF a.bank_account_id IS NOT NULL THEN SELECT * INTO ba FROM acct_bank_accounts WHERE id = a.bank_account_id; END IF;

  FOR it IN SELECT * FROM jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) LOOP
    IF it->>'account_id' IS DISTINCT FROM a.teller_account_id THEN
      RAISE EXCEPTION 'Transaction % belongs to account %, not %', it->>'id', it->>'account_id', a.teller_account_id;
    END IF;
    v_ids := v_ids || (it->>'id');
    INSERT INTO teller_transactions AS t (tenant_id, account_ref, teller_transaction_id, txn_date, amount_raw, description, status,
           processing_status, category, counterparty_name, counterparty_type, txn_type, running_balance, raw, feed_status)
    VALUES (a.tenant_id, a.id, it->>'id', (it->>'date')::date, (it->>'amount')::numeric, it->>'description', it->>'status',
            it#>>'{details,processing_status}', it#>>'{details,category}', it#>>'{details,counterparty,name}',
            it#>>'{details,counterparty,type}', it->>'type', nullif(it->>'running_balance','')::numeric, it,
            CASE WHEN it->>'status' = 'pending' THEN 'pending_only' ELSE 'held' END)
    ON CONFLICT (account_ref, teller_transaction_id) DO UPDATE
      SET txn_date = EXCLUDED.txn_date, amount_raw = EXCLUDED.amount_raw, description = EXCLUDED.description,
          status = EXCLUDED.status, processing_status = EXCLUDED.processing_status, category = EXCLUDED.category,
          counterparty_name = EXCLUDED.counterparty_name, counterparty_type = EXCLUDED.counterparty_type,
          txn_type = EXCLUDED.txn_type, running_balance = EXCLUDED.running_balance, raw = EXCLUDED.raw,
          last_seen_at = now(), removed_at = NULL,
          feed_status = CASE WHEN t.feed_status = 'in_feed' THEN 'in_feed'
                             WHEN EXCLUDED.status = 'pending' THEN 'pending_only' ELSE 'held' END
    RETURNING t.id, t.bank_transaction_id INTO v_tt, v_bt;
    n_up := n_up + 1;

    IF it->>'status' = 'pending' THEN n_pend := n_pend + 1; CONTINUE; END IF;
    IF v_bt IS NOT NULL THEN CONTINUE; END IF;                         -- already in the feed
    IF a.bank_account_id IS NULL OR NOT a.sync_enabled
       OR (a.feed_start_date IS NOT NULL AND (it->>'date')::date < a.feed_start_date) THEN CONTINUE; END IF;
    IF v_sign IS NULL THEN
      UPDATE teller_transactions SET feed_status = 'sign_unconfirmed' WHERE id = v_tt;
      n_hold := n_hold + 1; CONTINUE;
    END IF;

    -- books convention (part 3): amount > 0 is money IN
    v_amt := (it->>'amount')::numeric * v_sign;
    INSERT INTO acct_bank_transactions(tenant_id, entity_id, bank_account_id, transaction_date, posted_date, amount, currency,
           description, payee, provider_transaction_id, txn_type)
    VALUES (a.tenant_id, ba.entity_id, a.bank_account_id, (it->>'date')::date, (it->>'date')::date, v_amt, coalesce(ba.currency, a.currency),
            it->>'description', it#>>'{details,counterparty,name}', it->>'id',
            CASE WHEN v_amt >= 0 THEN 'deposit' ELSE 'expense' END)
    ON CONFLICT (bank_account_id, provider_transaction_id) WHERE provider_transaction_id IS NOT NULL DO NOTHING
    RETURNING id INTO v_bt;
    IF v_bt IS NULL THEN
      SELECT id INTO v_bt FROM acct_bank_transactions WHERE bank_account_id = a.bank_account_id AND provider_transaction_id = it->>'id';
    ELSE
      n_feed := n_feed + 1;
    END IF;
    UPDATE teller_transactions SET bank_transaction_id = v_bt, feed_status = 'in_feed' WHERE id = v_tt;
  END LOOP;

  IF p_full_window AND p_from IS NOT NULL AND p_to IS NOT NULL THEN
    UPDATE teller_transactions t SET feed_status = 'removed', removed_at = now()
     WHERE t.account_ref = a.id AND t.status = 'pending' AND t.removed_at IS NULL
       AND t.txn_date BETWEEN p_from AND p_to AND NOT (t.teller_transaction_id = ANY (v_ids));
    GET DIAGNOSTICS n_rem = ROW_COUNT;
  END IF;

  UPDATE teller_accounts SET last_synced_at = now() WHERE id = a.id;
  UPDATE teller_enrollments SET last_synced_at = now() WHERE id = a.enrollment_ref;
  UPDATE acct_bank_accounts SET last_sync_at = now() WHERE id = a.bank_account_id;
  RETURN QUERY SELECT n_up, n_feed, n_pend, n_rem, n_hold;
END $$;

-- @seq 593
CREATE FUNCTION public.teller_next_sync_window(p_account_ref uuid, OUT from_date date, OUT to_date date) RETURNS record
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce((SELECT max(txn_date) FROM teller_transactions WHERE account_ref = p_account_ref AND status = 'posted') - 10,
                  (SELECT coalesce(feed_start_date, current_date - 90) FROM teller_accounts WHERE id = p_account_ref)),
         current_date;
$$;

-- @seq 594
CREATE FUNCTION public.teller_process_webhook(p_inbox_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE w integration_webhook_inbox%ROWTYPE; e teller_enrollments%ROWTYPE; v_acct uuid; v_items jsonb; v_reason text; r record;
BEGIN
  SELECT * INTO w FROM integration_webhook_inbox WHERE id = p_inbox_id AND provider_code = 'teller' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Teller webhook %', p_inbox_id; END IF;
  IF w.status = 'processed' THEN RETURN 'already processed'; END IF;
  IF NOT w.signature_valid THEN
    UPDATE integration_webhook_inbox SET status = 'rejected', error = 'invalid signature', processed_at = now() WHERE id = w.id;
    RETURN 'rejected';
  END IF;
  IF w.provider_timestamp IS NOT NULL AND w.provider_timestamp < w.received_at - interval '3 minutes' THEN
    UPDATE integration_webhook_inbox SET status = 'rejected', error = 'timestamp older than 3 minutes (replay protection)', processed_at = now() WHERE id = w.id;
    RETURN 'rejected';
  END IF;

  BEGIN
    CASE w.event_type
      WHEN 'webhook.test' THEN
        UPDATE integration_webhook_inbox SET status = 'processed', processed_at = now(), attempts = attempts + 1 WHERE id = w.id;
        RETURN 'test';
      WHEN 'enrollment.disconnected' THEN
        SELECT * INTO e FROM teller_enrollments WHERE enrollment_id = w.payload#>>'{payload,enrollment_id}' FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Unknown enrollment %', w.payload#>>'{payload,enrollment_id}'; END IF;
        -- webhook reasons are 'disconnected[.x]'; API error codes are 'enrollment.disconnected[.x]' - store one form
        v_reason := w.payload#>>'{payload,reason}';
        v_reason := CASE WHEN v_reason LIKE 'enrollment.%' THEN v_reason ELSE 'enrollment.' || v_reason END;
        UPDATE teller_enrollments SET status = 'disconnected', disconnect_reason = v_reason, disconnected_at = now(), updated_at = now() WHERE id = e.id;
        UPDATE integration_connections SET status = 'needs_repair', status_reason = v_reason, updated_at = now() WHERE id = e.connection_id;
        UPDATE integration_webhook_inbox SET tenant_id = e.tenant_id, connection_id = e.connection_id WHERE id = w.id;
      WHEN 'transactions.processed' THEN
        v_items := coalesce(w.payload#>'{payload,transactions}', '[]'::jsonb);
        FOR r IN SELECT ta.id AS ref, ta.tenant_id, jsonb_agg(x) AS items
                   FROM jsonb_array_elements(v_items) x JOIN teller_accounts ta ON ta.teller_account_id = x->>'account_id'
                  GROUP BY ta.id, ta.tenant_id LOOP
          PERFORM teller_ingest_transactions(r.ref, r.items);
          UPDATE integration_webhook_inbox SET tenant_id = r.tenant_id WHERE id = w.id;
        END LOOP;
      WHEN 'account.number_verification.processed' THEN
        UPDATE teller_accounts SET verification_status = CASE w.payload#>>'{payload,status}' WHEN 'completed' THEN 'verified' ELSE 'expired' END,
               updated_at = now()
         WHERE teller_account_id = w.payload#>>'{payload,account_id}'
        RETURNING id INTO v_acct;
        IF v_acct IS NULL THEN RAISE EXCEPTION 'Unknown account %', w.payload#>>'{payload,account_id}'; END IF;
      ELSE
        UPDATE integration_webhook_inbox SET status = 'ignored', processed_at = now(), error = 'unhandled type' WHERE id = w.id;
        RETURN 'ignored';
    END CASE;
    UPDATE integration_webhook_inbox SET status = 'processed', processed_at = now(), attempts = attempts + 1, error = NULL WHERE id = w.id;
    RETURN 'processed';
  EXCEPTION WHEN OTHERS THEN
    UPDATE integration_webhook_inbox SET status = 'failed', attempts = attempts + 1, error = SQLERRM WHERE id = w.id;
    RETURN 'failed: ' || SQLERRM;
  END;
END $$;

-- @seq 595
CREATE FUNCTION public.teller_record_api_error(p_enrollment_ref uuid, p_http_status integer, p_error_code text, p_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE e teller_enrollments%ROWTYPE;
BEGIN
  SELECT * INTO e FROM teller_enrollments WHERE id = p_enrollment_ref FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF p_error_code LIKE 'enrollment.disconnected%' THEN
    UPDATE teller_enrollments SET status = 'disconnected', disconnect_reason = p_error_code, disconnected_at = now() WHERE id = e.id;
    UPDATE integration_connections SET status = 'needs_repair', status_reason = p_error_code WHERE id = e.connection_id;
  ELSIF p_http_status = 403 THEN
    UPDATE teller_enrollments SET status = 'revoked' WHERE id = e.id;
    UPDATE integration_connections SET status = 'revoked', status_reason = coalesce(p_error_code, 'access token invalid or revoked') WHERE id = e.connection_id;
  END IF;
  UPDATE integration_connections SET last_error_at = now(), last_error = coalesce(p_message, p_error_code),
         consecutive_failures = consecutive_failures + 1 WHERE id = e.connection_id;
END $$;

-- @seq 596
CREATE FUNCTION public.teller_record_balance(p_account_ref uuid, p_ledger text, p_available text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  INSERT INTO teller_balances(tenant_id, account_ref, ledger, available)
  SELECT tenant_id, id, nullif(p_ledger,'')::numeric, nullif(p_available,'')::numeric FROM teller_accounts WHERE id = p_account_ref;
$$;

-- @seq 597
CREATE FUNCTION public.teller_register_enrollment(p_tenant_id uuid, p_enrollment_id text, p_teller_user_id text, p_institution_name text, p_environment text, p_access_token_secret_id uuid, p_signature_verified boolean, p_products text[] DEFAULT ARRAY['transactions'::text, 'balance'::text], p_institution_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_conn uuid; v_id uuid;
BEGIN
  IF NOT p_signature_verified THEN
    RAISE EXCEPTION 'Teller Connect signature was not verified; refusing enrollment %', p_enrollment_id;
  END IF;
  INSERT INTO integration_connections(tenant_id, provider_code, environment, external_account_id, display_name, status, credential_secret_id, scopes, connected_by)
  VALUES (p_tenant_id, 'teller', p_environment, p_enrollment_id, p_institution_name, 'active', p_access_token_secret_id, p_products, auth.uid())
  ON CONFLICT (tenant_id, provider_code, environment, external_account_id)
  DO UPDATE SET status = 'active', status_reason = NULL, credential_secret_id = EXCLUDED.credential_secret_id,
                scopes = EXCLUDED.scopes, updated_at = now()
  RETURNING id INTO v_conn;

  INSERT INTO teller_enrollments(tenant_id, connection_id, enrollment_id, teller_user_id, institution_id, institution_name, environment,
                                 products, access_token_secret_id, connect_signature_verified, status)
  VALUES (p_tenant_id, v_conn, p_enrollment_id, p_teller_user_id, p_institution_id, p_institution_name, p_environment,
          p_products, p_access_token_secret_id, true, 'active')
  ON CONFLICT (enrollment_id) DO UPDATE
    SET status = 'active', disconnect_reason = NULL, repaired_at = CASE WHEN teller_enrollments.status <> 'active' THEN now() END,
        access_token_secret_id = EXCLUDED.access_token_secret_id, products = EXCLUDED.products, updated_at = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;

-- @seq 598
CREATE FUNCTION public.teller_upsert_account(p_enrollment_ref uuid, p_account jsonb, p_bank_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE e teller_enrollments%ROWTYPE; v_id uuid;
BEGIN
  SELECT * INTO e FROM teller_enrollments WHERE id = p_enrollment_ref;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown enrollment %', p_enrollment_ref; END IF;
  IF p_bank_account_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM acct_bank_accounts WHERE id = p_bank_account_id AND tenant_id = e.tenant_id) THEN
    RAISE EXCEPTION 'Bank register % does not belong to this tenant', p_bank_account_id;
  END IF;
  INSERT INTO teller_accounts(tenant_id, enrollment_ref, teller_account_id, bank_account_id, name, account_type, subtype, currency,
                              last_four, institution_id, institution_name, status)
  VALUES (e.tenant_id, e.id, p_account->>'id', p_bank_account_id, p_account->>'name', p_account->>'type', p_account->>'subtype',
          coalesce(p_account->>'currency','USD'), p_account->>'last_four', p_account#>>'{institution,id}',
          p_account#>>'{institution,name}', coalesce(p_account->>'status','open'))
  ON CONFLICT (teller_account_id) DO UPDATE
    SET name = EXCLUDED.name, subtype = EXCLUDED.subtype, status = EXCLUDED.status, last_four = EXCLUDED.last_four,
        bank_account_id = coalesce(EXCLUDED.bank_account_id, teller_accounts.bank_account_id), updated_at = now()
  RETURNING id INTO v_id;
  UPDATE acct_bank_accounts SET provider = 'teller', provider_connection_id = e.enrollment_id, provider_account_id = p_account->>'id',
         masked_account_number = coalesce(masked_account_number, '****' || (p_account->>'last_four'))
   WHERE id = (SELECT bank_account_id FROM teller_accounts WHERE id = v_id);
  RETURN v_id;
END $$;

